1	export interface BudgetDay {
2	  day: number;
3	  title: string;
4	  activities: string[];
5	  costUsd: number;
6	}
7	
8	export interface BudgetPlan {
9	  intro: string;
10	  days: BudgetDay[];
11	  hiddenGem: { title: string; description: string };
12	  localFood: { dish: string; description: string };
13	  totalUsd: number;
14	}
15	
16	export type BudgetResult = { ok: true; plan: BudgetPlan } | { ok: false };
17	
18	function isRecord(v: unknown): v is Record<string, unknown> {
19	  return typeof v === "object" && v !== null && !Array.isArray(v);
20	}
21	
22	function isNonEmptyString(v: unknown): v is string {
23	  return typeof v === "string" && v.trim().length > 0;
24	}
25	
26	/**
27	 * Valida el plan (cada día con costUsd entero >= 0) y calcula totalUsd como la
28	 * suma de los días, ignorando el total que traiga el modelo.
29	 */
30	export function applyBudget(plan: unknown): BudgetResult {
31	  if (!isRecord(plan) || !isNonEmptyString(plan.intro)) return { ok: false };
32	  const { days, hiddenGem, localFood } = plan;
33	  if (!Array.isArray(days) || days.length === 0) return { ok: false };
34	  if (!isRecord(hiddenGem) || !isNonEmptyString(hiddenGem.title) || !isNonEmptyString(hiddenGem.description)) {
35	    return { ok: false };
36	  }
37	  if (!isRecord(localFood) || !isNonEmptyString(localFood.dish) || !isNonEmptyString(localFood.description)) {
38	    return { ok: false };
39	  }
40	
41	  const parsedDays: BudgetDay[] = [];
42	  for (const d of days) {
